import math
from hyprchan.core.animations.avatar3d.emote_api import animate

def pose(t):
    if t < 0.2:
        a = t / 0.2
        return {
            "expressions": {"brow_up": 0.25 * a, "eyes_wide": 0.35 * a, "mouth_small": 0.25 * a},
            "bones": {"head": [0, 0, -3 * a], "neck": [0, 0, 2 * a]}
        }
    if t < 0.68:
        a = (t - 0.2) / 0.48
        return {
            "expressions": {"eyes_wide": 0.55, "brow_angry": 0.18, "puff": 0.9, "mouth_close": 1, "smile": 0, "blush": 0.25},
            "bones": {"head": [0, 0, -3 - 8 * a], "neck": [0, 0, 2 + 2 * a]}
        }
    a = (t - 0.68) / 0.32
    return {
        "expressions": {"eyes_wide": 0.55 * (1-a), "brow_angry": 0.18 * (1-a), "puff": 0.9 * (1-a), "mouth_close": 0, "smile": 0.72 * a, "joy": 0.25 * a, "blush": 0.25 * (1-a)},
        "bones": {"head": [0, 0, -11 * (1-a)], "neck": [0, 0, 4 * (1-a)]}
    }

animate(4.0, pose)
